function pickBestOption(options) {
  return options.reduce((best, o) => (o.ev > best.ev ? o : best)).label;
}

items.starterCode:
function sampleOutcome(outcomes, roll) {
  // TODO: accumulate probability across outcomes, return the value
  // of the first outcome whose cumulative probability exceeds roll
}

items.solution:
function sampleOutcome(outcomes, roll) {
  let cumulative = 0;
  for (const outcome of outcomes) {
    cumulative += outcome.probability;
    if (roll < cumulative) return outcome.value;
  }
  return outcomes[outcomes.length - 1].value;
}

